testCmd.command:
cat > repro.tmp.mjs <<'EOF'
import { hedgedDistill } from './src/distill.js'
import { fakeServer } from './test/helpers.mjs'
const N = Number(process.argv[2] || 10)
const primaryDelayMs = Number(process.argv[3] || 1500)
const hedgeAfterMs = Number(process.argv[4] || 1600)
let fail = 0
for (let i = 0; i < N; i++) {
  const s = fakeServer({ primaryDelayMs, status: 200 })
  const meta = await hedgedDistill(s.url, { hedgeAfterMs })
  if (meta.hedgeStartedAt !== null) { fail++; console.log('  FAIL iter', i, 'hedgeStartedAt=', meta.hedgeStartedAt) }
  s.close()
}
console.log('runs', N, 'fails', fail)
EOF
node repro.tmp.mjs 10
